tufteTheme.styles:
body[data-tufte-theme=lenticule-laboratory]{color-scheme:light;--tufte-bg:#F0F7F5;--tufte-surface:#FFFFFF;--tufte-ink:#123431;--tufte-muted:#496760;--tufte-line:#657D76;--tufte-accent:#00695C;--tufte-radius:.3rem;--tufte-gap:1rem;}
@media(prefers-color-scheme:dark){body[data-tufte-theme=lenticule-laboratory]{color-scheme:dark;--tufte-bg:#102524;--tufte-surface:#183632;--tufte-ink:#E6F6F1;--tufte-muted:#B5CDC6;--tufte-line:#97ACA6;--tufte-accent:#8FE6D0;}}
body[data-tufte-theme=lenticule-laboratory] a:focus-visible,body[data-tufte-theme=lenticule-laboratory] button:focus-visible{outline:3px solid var(--tufte-accent);outline-offset:3px;}
body[data-tufte-theme=lenticule-laboratory] .tufte-shell{width:min(1110px,100%);}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead{padding:.95rem 0 1.15rem;border-bottom:3px double var(--tufte-accent);}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead h1{font-family:Georgia,"Iowan Old Style",serif;font-size:clamp(1.9rem,4vw,2.8rem);letter-spacing:-.02em;}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile{border-left:3px solid var(--tufte-accent);border-radius:.1rem;padding:1rem 1.15rem;}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile h2{font-family:Georgia,serif;text-transform:none;letter-spacing:0;font-size:.9rem;color:var(--tufte-accent);}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body{font-family:Georgia,"Iowan Old Style",serif;font-size:1.07rem;line-height:1.7;}
